//
// Fonts. Text comes in three sizes: small (1), medium (2) and large (3). The "classic" font is the built-in 5x7 pixel
// font scaled up. The others are bitmaps of real typefaces with soft edges, generated by tools/make_fonts.py.
#pragma once
#include <stddef.h>
#include <stdint.h>

namespace rm {

struct Glyph {
  uint16_t offset;      // where its bitmap starts in the face's data
  uint8_t w;            // bitmap width in pixels (its height is the face's)
  int8_t left;          // pixels from the pen position to the bitmap's left edge
  uint8_t advance;      // pixels to move the pen on
};

// One size of one font: 96 glyphs (printable ASCII 32..126, then the degree sign). Bitmaps are 4 bits a pixel, two
// pixels a byte, each row starting on a byte.
struct FontFace {
  uint8_t height;
  const Glyph *glyphs;
  const uint8_t *data;
};

struct Font {
  const char *id;       // what is stored in settings
  const char *name;     // what the settings page shows
  const FontFace *face[3];   // small, medium, large; nullptr means the built-in pixel font at that scale
};

extern const Font FONTS[];
extern const int FONT_COUNT;

int fontIndex(const char *id);            // -1 if there is no such font
void setFont(int index);                  // out-of-range falls back to the classic font
int currentFont();
int lineHeight(int size);                 // of the current font; size 1..3

// [{"id":"classic","name":"Classic pixel"},...] for the settings page. Returns the length, or 0 if it does not fit.
size_t fontsJson(char *out, size_t out_size);

}  // namespace rm
